/// Write a `Alignment` as its element, `x:alignment`.
#[must_use]
pub fn alignment(node: &super::Alignment, scope: &mut markup::Scope) -> xml::element::Element {
    let mut writer = markup::Writer::new(scope, &super::ALIGNMENT_SHAPE, &node.unknown);
    writer.attribute(0, &node.horizontal);
    writer.attribute(1, &node.vertical);
    writer.attribute(2, &node.text_rotation);
    writer.attribute(3, &node.wrap_text);
    writer.attribute(4, &node.indent);
    writer.attribute(5, &node.relative_indent);
    writer.attribute(6, &node.justify_last_line);
    writer.attribute(7, &node.shrink_to_fit);
    writer.attribute(8, &node.reading_order);
    writer.finish()
}

